let schedules = flow.get('schedulesParameters');
let currentSchedule = schedules[msg.nbr];

let events = msg.payload;
const address = {
    address: currentSchedule.targetip + ":" + flow.get("portdest")
};

function addHours(date, h) {
    return new Date(new Date(date).getTime() + h * 60 * 60 * 1000);
}

async function main() {
    try {
        for (let i = 0; i < events.length; i++) {

            let date = addHours(events[i].eventStart, flow.get("UTCoffset"));
            let timestart = addHours(events[i].eventStart, flow.get("UTCoffset"));
            let timeend = addHours(events[i].eventEnd, flow.get("UTCoffset"));

            const exceptionSchedule = [
                {
                    date: {
                        type: 10, // DATE
                        value: date
                    },
                    events: [
                        {
                            time: {
                                type: 11, // TIME
                                value: timestart,
                            },
                            value: {
                                type: 4, //REAL
                                value: currentSchedule.exeptionValue
                            },
                        },
                        {
                            time: {
                                type: 11,
                                value: timeend,
                            },
                            value: {
                                type: 4, //REAL
                                value: currentSchedule.defaultValue
                            },
                        },
                    ],
                    priority: { type: 2, value: 16 }, 
                }
            ];

            await client.writeProperty(
                address,
                {
                    type: bacnet.ObjectType.SCHEDULE,
                    instance: currentSchedule.scheduleid
                },
                bacnet.PropertyIdentifier.EXCEPTION_SCHEDULE,
                exceptionSchedule,
                {}
            );
            node.warn('Ecriture EXCEPTION_SCHEDULE réussie' + ' schedule id: ' + currentSchedule.scheduleid + ' target ip: ' + currentSchedule.targetip + " from " + timestart + " to " + timeend);

        }

        node.warn('Ecriture EXCEPTION_SCHEDULE réussie' + ' schedule id: ' + currentSchedule.scheduleid + ' target ip: ' + currentSchedule.targetip);
        return { calNbr: msg.calNbr };

    } catch (err) {
        node.error('Erreur: ' + JSON.stringify(err, Object.getOwnPropertyNames(err)));
    } finally {
        client.close();
    }
}

main();

